    chapterEl.innerHTML=`<option value="">${courseEl.value?'Select chapter…':'Select a course first…'}</option>${allowed.map(ch=>`<option value="${esc(ch.id)}">${esc(ch.chapter_number)} — ${esc(ch.title)}</option>`).join('')}`;
